sys_script_include.script:
var hr_TaskTicketUtilSNC = Class.create();
hr_TaskTicketUtilSNC.prototype = {

    initialize: function() {
		this.CLOSED_STATE ="3";
		this.SKIPPED_STATE = "9";
		this.INCOMPLETE_STATE = "4";	
		this.CLOSED_COMPLETE_STATE = "3";
    },

	getClosedStateValue : function() {
		return this.CLOSED_STATE;
	},

	getSkippedStateValue : function() {
		return this.SKIPPED_STATE;
	},

	getIncompleteStateValue : function() {
		return this.INCOMPLETE_STATE;
	},

	getClosedCompleteStateValue: function(){
		return this.CLOSED_COMPLETE_STATE;
	},

    type: 'hr_TaskTicketUtilSNC'
};
